(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],reduced=matchMedia('(prefers-reduced-motion: reduce)');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const textTree=v=>!v?'':typeof v==='string'?v:Array.isArray(v)?v.map(textTree).join(' '):v.text||textTree(v.children||v.root||'');
const instances=new Map();
if(window.rive)rive.RuntimeLoader.setWasmUrl('/assets/rive.wasm');
function mount(canvas){if(instances.has(canvas)||!canvas.dataset.rive||!window.rive||!canvas.isConnected)return;let r;try{r=new rive.Rive({src:canvas.dataset.rive,canvas,autoplay:false,layout:new rive.Layout({fit:rive.Fit.Contain,alignment:rive.Alignment.Center}),onLoad:()=>{r.resizeDrawingSurfaceToCanvas();const machine=r.stateMachineNames[0];if(machine)r.play(machine);else r.play();if(reduced.matches)setTimeout(()=>r.pause(),700)},onLoadError:()=>{canvas.parentElement.innerHTML='<div class="replica-rive-fallback"><a href="https://calendly.com/">Explore the product on Calendly ↗</a></div>'}});instances.set(canvas,r)}catch(e){console.error('Product animation unavailable',e)}}
const observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(isIntersecting){mount(target);const r=instances.get(target);if(r?.loaded&&!reduced.matches)r.play()}else instances.get(target)?.pause()}),{rootMargin:'100px'});
function observe(root=document){$$('canvas[data-rive]',root).forEach(c=>observer.observe(c))}function dispose(root){$$('canvas',root).forEach(c=>{observer.unobserve(c);instances.get(c)?.cleanup();instances.delete(c)})}
new ResizeObserver(()=>instances.forEach(r=>r.resizeDrawingSurfaceToCanvas())).observe(document.documentElement);
function canvas(src,title){return `<canvas data-rive="${esc(src)}" role="img" aria-label="${esc(title)}" style="width:100%;height:100%;display:block"></canvas>`}
function features(root,d){const heading=$('[data-testid=content-block]',root)?.innerHTML||'';const reversed=root.dataset.component==='FeatureAccordionIsland'&&root.closest('section')?.id.includes('Callie')||root.closest('section')?.id.includes('Payments');root.innerHTML=`<div class="replica-feature-layout ${reversed?'reverse':''}"><div><div data-testid="content-block">${heading}</div><div class="replica-features">${d.items.map((x,i)=>`<div class="replica-feature-row ${i===0?'active':''}"><button type="button" aria-expanded="${i===0}" aria-controls="feature-${d.id}-${i}">${x.icon?.url?`<img alt="" src="${esc(x.icon.url)}">`:'<span aria-hidden="true">✧</span>'}<span>${esc(x.title)}</span><span aria-hidden="true">${i===0?'−':'+'}</span></button><div id="feature-${d.id}-${i}" class="replica-feature-copy"><p>${esc(x.description)}</p><a href="${esc(x.href)}">Learn more ↗</a><div class="replica-mobile-visual">${canvas(x.riveFileSrc,x.title)}</div></div></div>`).join('')}</div></div><div class="replica-feature-visual">${canvas(d.items[0].riveFileSrc,d.items[0].title)}</div></div>`;$$('.replica-feature-row button',root).forEach((b,i)=>b.addEventListener('click',()=>{$$('.replica-feature-row',root).forEach((row,j)=>{row.classList.toggle('active',i===j);const button=$('button',row);button.setAttribute('aria-expanded',String(i===j));button.lastElementChild.textContent=i===j?'−':'+'});const visual=$('.replica-feature-visual',root);dispose(visual);visual.innerHTML=canvas(d.items[i].riveFileSrc,d.items[i].title);observe(root);requestAnimationFrame(()=>instances.forEach(r=>r.resizeDrawingSurfaceToCanvas()))}))}
function hero(root){const tabs=$$('[role=tab]',root),panels=$$('[role=tabpanel]',root);panels.forEach(p=>p.classList.add('replica-hero-panel'));function select(i){tabs.forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1;b.style.filter=i===j?'none':'grayscale(1)';b.style.opacity=i===j?'1':'.55'});panels.forEach((p,j)=>{p.style.opacity=i===j?'1':'0';p.style.pointerEvents=i===j?'auto':'none';p.inert=i!==j;p.setAttribute('aria-hidden',String(i!==j));if(i===j){p.classList.remove('pointer-events-none');$$('canvas',p).forEach(c=>{mount(c);const r=instances.get(c);if(r?.loaded){r.resizeDrawingSurfaceToCanvas();if(!reduced.matches)r.play()}})}else $$('canvas',p).forEach(c=>instances.get(c)?.pause())});const track=$('[data-testid=multi-product-hero-gradient-track]',root);if(track){track.style.transition='filter 700ms';track.style.filter=`hue-rotate(${[0,55,190,285][i]}deg)`}}tabs.forEach((b,i)=>{b.addEventListener('click',()=>select(i));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;select(next);tabs[next].focus()}})});select(0)}
function header(root){const head=$('header',root),toggle=$('[aria-label="Open menu"]',root),mobile=$('[data-mobile-panel]',root);let activeButton=null;const mega=document.createElement('div');mega.className='replica-mega';mega.hidden=true;head.append(mega);const groups=mobile?$$('nav>div',mobile).filter(x=>$('button',x)):[];const close=()=>{mega.hidden=true;if(activeButton)activeButton.setAttribute('aria-expanded','false');activeButton=null};$$('header nav button',root).forEach((b,i)=>b.addEventListener('click',()=>{const open=activeButton!==b;close();if(!open)return;activeButton=b;b.setAttribute('aria-expanded','true');mega.replaceChildren();const inner=$('.overflow-hidden',groups[i]);if(inner){const content=inner.cloneNode(true);content.style.cssText='display:contents';mega.append(content);$$('[style]',content).forEach(x=>{if(/height:0|opacity:0/.test(x.getAttribute('style')))x.style.cssText='height:auto;opacity:1'});$$('a',content).forEach(a=>a.removeAttribute('tabindex'))}mega.hidden=false}));function mobileOpen(open){if(!mobile)return;toggle.setAttribute('aria-expanded',String(open));mobile.style.top=head.getBoundingClientRect().bottom+'px';mobile.style.opacity=open?'1':'0';mobile.style.visibility=open?'visible':'hidden';mobile.inert=!open;document.body.style.overflow=open?'hidden':'';const icons=$$('svg',toggle);icons.forEach((x,i)=>{x.style.opacity=(open?i===1:i===0)?'1':'0';x.style.transform='none'})}if(mobile){mobile.inert=true;toggle.addEventListener('click',()=>mobileOpen(toggle.getAttribute('aria-expanded')!=='true'));$('[aria-label="Close navigation"]',mobile)?.addEventListener('click',()=>mobileOpen(false));groups.forEach(g=>{const b=$('button',g),panel=$('.overflow-hidden',g);if(!b||!panel)return;panel.hidden=true;b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));panel.hidden=!open;panel.style.height=open?'auto':'0';panel.style.opacity=open?'1':'0'})})}document.addEventListener('click',e=>{if(!head.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const last=activeButton;close();mobileOpen(false);(last||toggle)?.focus()}});const dismiss=$('[aria-label="Dismiss announcement"]',head);dismiss?.addEventListener('click',()=>{dismiss.parentElement.remove()})}
function timeline(root,d){root.innerHTML=`<div class="replica-timeline">${d.cards.map((c,i)=>`<article class="replica-timeline-card ${i===0?'active':''}" tabindex="0" role="button" aria-expanded="${i===0}"><div class="replica-timeline-copy"><h3>${esc(c.heading)}</h3><p>${esc(c.restingDescription)}</p></div><img loading="lazy" src="${esc(c.restingVisual.src)}" alt="${esc(c.heading)}"></article>`).join('')}</div>`;$$('.replica-timeline-card',root).forEach((el,i)=>{const activate=()=>{$$('.replica-timeline-card',root).forEach((x,j)=>{const open=i===j;x.classList.toggle('active',open);x.setAttribute('aria-expanded',String(open));$('p',x).textContent=open?textTree(d.cards[j].activeContent).split('  ')[0]:d.cards[j].restingDescription;$('img',x).src=open&&d.cards[j].activeVisual?.src?d.cards[j].activeVisual.src:d.cards[j].restingVisual.src})};el.addEventListener('click',activate);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}})})}
function stories(root,d){const old=$('[data-testid=use-case-carousel]',root),heading=old?.firstElementChild.outerHTML||'';root.innerHTML=`<div>${heading}<div class="replica-stories" aria-live="polite"></div><div class="replica-story-controls" role="tablist" aria-label="Customer stories">${d.cards.map((c,i)=>`<button role="tab" aria-label="${esc(c.person.name)}" aria-selected="${i===0}" tabindex="${i===0?0:-1}"></button>`).join('')}</div>`;const area=$('.replica-stories',root),buttons=$$('.replica-story-controls button',root);function select(i){const c=d.cards[i],prev=d.cards[(i+d.cards.length-1)%d.cards.length],next=d.cards[(i+1)%d.cards.length];area.innerHTML=`<button class="replica-story-preview" aria-label="Previous customer story"><img src="${esc(prev.backgroundImage.src)}" alt=""></button><article class="replica-story-main"><div class="replica-story-copy"><h3>${esc(c.headline)}</h3><div><blockquote>${esc(textTree(c.statement))}</blockquote><small>${esc(c.person.name)}<br>${esc(c.person.role)}</small></div></div><img src="${esc(c.featuredImage.src)}" alt="${esc(c.featuredImage.alt)}"></article><button class="replica-story-preview" aria-label="Next customer story"><img src="${esc(next.backgroundImage.src)}" alt=""></button>`;const arrows=$$('button',area);arrows[0].onclick=()=>select((i+d.cards.length-1)%d.cards.length);arrows[1].onclick=()=>select((i+1)%d.cards.length);buttons.forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1})}buttons.forEach((b,i)=>{b.onclick=()=>select(i);b.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const next=(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;select(next);buttons[next].focus()}}});select(0)}
function dialog(title,message,trigger){const layer=document.createElement('div');layer.className='replica-dialog';layer.innerHTML=`<div role="dialog" aria-modal="true" aria-labelledby="replica-dialog-title"><h2 id="replica-dialog-title">${esc(title)}</h2><p>${esc(message)}</p><button type="button">Close</button></div>`;document.body.append(layer);const close=()=>{layer.remove();trigger?.focus()};$('button',layer).onclick=close;layer.onclick=e=>{if(e.target===layer)close()};layer.onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){e.preventDefault();$('button',layer).focus()}};$('button',layer).focus()}
fetch('/page-data.json').then(r=>{if(!r.ok)throw Error('Page data unavailable');return r.json()}).then(data=>{data.forEach(d=>{const root=$(`[data-component-id="${d.id}"]`);if(!root)return;switch(d.type){case'MultiProductHeroInteractive':hero(root);break;case'StickyCarouselIsland':case'FeatureAccordionIsland':features(root,d);break;case'StatsigHomepageHeaderIsland':header(root);break;case'TimelineFeatureDeck':timeline(root,d);break;case'UseCaseCarousel':stories(root,d);break}});observe();$$('button').filter(b=>/Sign up with (Google|Microsoft)/.test(b.textContent)).forEach(b=>b.addEventListener('click',()=>location.href='https://calendly.com/signup'));$$('footer button,[data-component=GlobalFooterIsland] button').forEach(b=>{if(/Cookie Settings|Your Privacy Choices/.test(b.textContent))b.onclick=()=>dialog('Privacy in this recreation','This local recreation has no analytics, advertising cookies, or account tracking. Account and sign-up links take you to the official Calendly website.',b);if(b.getAttribute('aria-haspopup')==='listbox')b.onclick=()=>{const d=data.find(d=>d.type==='GlobalFooterIsland');const languages=Array.isArray(d?.languages)?d.languages:[];const panel=document.createElement('div');panel.className='replica-dialog';panel.innerHTML='<div role="dialog" aria-modal="true" aria-label="Choose language"><h2>Choose language</h2>'+languages.map(l=>`<p><a href="${esc(typeof l.href==='string'?new URL(l.href,'https://calendly.com').href:'https://calendly.com/'+(l.code||''))}">${esc(l.label||l.name||l.code||'English')}</a></p>`).join('')+'<button>Close</button></div>';document.body.append(panel);$('button',panel).onclick=()=>{panel.remove();b.focus()};$('button',panel).focus();panel.onkeydown=e=>{if(e.key==='Escape'){panel.remove();b.focus()}}}})}).catch(e=>console.error(e));
})();
